        answer: "Khi trời nóng, hãy chơi vào sáng sớm hoặc chiều tối, uống nước trước khi khát, và nghỉ trong bóng râm lúc đổi sân với khăn lạnh trên cổ. Dừng ngay nếu bạn thấy chóng mặt, buồn nôn, yếu người, hoặc bị đau đầu hay chuột rút: vào chỗ râm mát, làm mát cơ thể, uống nước, và đi khám bác sĩ nếu không sớm thấy khá hơn. Nếu ai đó trở nên lú lẫn, ngất xỉu hoặc da rất nóng, hãy gọi cấp cứu ngay.",
