        answer: "Lỗi tự đánh hỏng (unforced error) là đánh hỏng một quả bóng mà bạn có đủ thời gian và vị trí để đánh tốt, như đánh vào lưới một quả bóng đánh qua lại dễ. Lỗi bị ép (forced error) là đánh hỏng do cú đánh tốt của đối thủ, chẳng hạn một quả bóng nhanh vượt quá tầm với. Ranh giới giữa hai loại là do đánh giá chủ quan, nên những người thống kê khác nhau có thể đếm cùng một trận khác nhau.",
