        answer: "Cả hai ở cuối sân là đội hình phòng thủ, hữu ích khi đội kia đang vô lê tốt, người đứng lưới của họ liên tục cắt các cú trả của bạn, hoặc bạn đang gặp những cú giao mạnh. Nó cho bạn thêm thời gian và khiến bóng lốp ít nguy hiểm hơn. Đổi lại, rất khó thắng điểm từ đó, nên hãy dùng bóng sâu và bóng lốp để đẩy đội kia lùi lại, và cùng nhau tiến lên khi được bóng ngắn.",
